using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Playables;using UnityEngine.Animations;using Sandbox.CharacterSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class ReviewLioraActualClothingFit {
 const string Data="Data/Liora/ClothingFit/";const string Target="Assets/_Sandbox/Characters/Liora/Candidate/Liora_Outfit_Fitted.asset";
 static Mesh Snapshot(SkinnedMeshRenderer r,Transform root){var source=r.sharedMesh;var p=source.vertices;var n=source.normals;var t=source.tangents;var dp=new Vector3[p.Length];var dn=new Vector3[p.Length];var dt=new Vector3[p.Length];for(int s=0;s<source.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;source.GetBlendShapeFrameVertices(s,0,dp,dn,dt);for(int j=0;j<p.Length;j++){p[j]+=dp[j]*w;n[j]+=dn[j]*w;t[j]+=new Vector4(dt[j].x,dt[j].y,dt[j].z,0)*w;}}
 var m=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*source.bindposes[j]).ToArray();var mn=m.Select(x=>x.inverse.transpose).ToArray();var op=new Vector3[p.Length];var on=new Vector3[p.Length];var ot=new Vector4[p.Length];using(var cs=source.GetBonesPerVertex())using(var ws=source.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++){Vector3 tangent=Vector3.zero;for(int k=0;k<cs[j];k++){var w=ws[at++];op[j]+=m[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;on[j]+=mn[w.boneIndex].MultiplyVector(n[j])*w.weight;tangent+=m[w.boneIndex].MultiplyVector(t[j])*w.weight;}on[j].Normalize();tangent.Normalize();ot[j]=new Vector4(tangent.x,tangent.y,tangent.z,t[j].w);}}
 var result=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};result.vertices=op;result.normals=on;result.tangents=ot;result.uv=source.uv;result.subMeshCount=source.subMeshCount;for(int j=0;j<source.subMeshCount;j++)result.SetTriangles(source.GetTriangles(j),j);result.RecalculateBounds();return result;}
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");File.Copy(Data+"outfit_preserved.asset",Target,true);AssetDatabase.ImportAsset(Target,ImportAssetOptions.ForceUpdate);Directory.CreateDirectory(Data+"ActualPreviews");var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");var scene=EditorSceneManager.NewPreviewScene();
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var outfit=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Outfit");var baseline=JObject.Parse(File.ReadAllText(Data+"binding_input.json"));var old=AssetDatabase.LoadAssetAtPath<Mesh>((string)baseline["outfitMesh"]);var oldBones=baseline["clothBonePaths"].Select(p=>root.transform.Find((string)p)).ToArray();var config=JObject.Parse(File.ReadAllText(Data+"candidate.json"));var fitted=AssetDatabase.LoadAssetAtPath<Mesh>(Target);var fittedBones=config["bonePaths"].Select(p=>root.transform.Find((string)p)).ToArray();var animator=root.GetComponentInChildren<Animator>(true);var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));var clips=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox/Data"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip).GroupBy(d=>d.name).ToDictionary(g=>g.Key,g=>g.First());
 var cameraGo=new GameObject("Garment comparison camera");SceneManager.MoveGameObjectToScene(cameraGo,scene);var camera=cameraGo.AddComponent<Camera>();camera.scene=scene;camera.cameraType=CameraType.Preview;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.15f,.18f);camera.orthographic=true;camera.orthographicSize=.37f;camera.nearClipPlane=.01f;camera.farClipPlane=10;
 foreach(var setting in new[]{(angle:new Vector3(25,155,0),power:1.4f),(angle:new Vector3(-15,215,0),power:.7f),(angle:new Vector3(15,25,0),power:.8f)}){var go=new GameObject("Fit review light");SceneManager.MoveGameObjectToScene(go,scene);var light=go.AddComponent<Light>();light.type=LightType.Directional;light.intensity=setting.power;light.cullingMask=1<<30;go.transform.rotation=Quaternion.Euler(setting.angle);}
 var files=new List<string>();foreach(var pose in new[]{(name:"Neutral",phase:0f),(name:"Thinking",phase:1/3f),(name:"Thinking",phase:.5f),(name:"Thinking",phase:2/3f),(name:"Talking",phase:.25f),(name:"Talking",phase:.5f),(name:"Talking",phase:.75f),(name:"Waving",phase:.25f),(name:"Waving",phase:.5f),(name:"Thumbs Up",phase:.5f)}){
 foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}outfit.sharedMesh=old;outfit.bones=oldBones;for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);
 if(pose.name!="Neutral"){var graph=PlayableGraph.Create("Liora garment static review");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,clips[pose.name].Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();p.SetTime(clips[pose.name].Clip.length*pose.phase);graph.Evaluate(0);}finally{graph.Destroy();}}
 if(pose.name=="Thinking"||pose.name=="Talking"){face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("viseme_aa"),60);face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("emo_joy"),25);}if(pose.name=="Waving")face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("emo_joy"),60);if(pose.name=="Thinking"||pose.name=="Talking"||pose.name=="Waving"){for(int si=0;si<face.sharedMesh.blendShapeCount;si++)face.SetBlendShapeWeight(si,0);string activityName=pose.name=="Thinking"?"Thinking":pose.name=="Talking"?"Speaking happy":"Greeting";var activity=AssetDatabase.LoadAssetAtPath<ActivityDefinition>("Assets/_Sandbox/Data/Activity/"+activityName+".asset");if(activity.Expression)foreach(var target in activity.Expression.Targets)face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex(target.Shape),target.Weight);if(pose.name=="Talking")face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex("viseme_aa"),60);}root.GetComponent<CharacterFacialMeshSync>()?.Apply();
 foreach(bool after in new[]{false,true}){outfit.sharedMesh=after?fitted:old;outfit.bones=after?fittedBones:oldBones;var objects=new List<GameObject>();var meshes=new List<Mesh>();try{foreach(var r in new[]{face,outfit}){var mesh=Snapshot(r,root.transform);meshes.Add(mesh);var go=new GameObject("Evaluated "+r.name);SceneManager.MoveGameObjectToScene(go,scene);go.layer=30;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;objects.Add(go);}
 foreach(var view in new[]{(name:"Front",direction:new Vector3(0,0,3)),(name:"Side",direction:new Vector3(3,0,1)),(name:"Back",direction:new Vector3(0,0,-3))}){var center=new Vector3(0,1.255f,0);camera.transform.position=center+view.direction;camera.transform.LookAt(center);var rt=RenderTexture.GetTemporary(768,900,24);var previous=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(768,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,768,900),0,0);tex.Apply();string file=Data+"ActualPreviews/"+pose.name.Replace(" ","")+"_"+pose.phase.ToString("F3")+"_"+view.name+"_"+(after?"After":"Before")+".png";File.WriteAllBytes(file,tex.EncodeToPNG());files.Add(file);UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}}
 }finally{foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);foreach(var mesh in meshes)UnityEngine.Object.DestroyImmediate(mesh);}}
 }File.WriteAllText(Data+"actual_activity_render_review.json",JsonConvert.SerializeObject(new{files,explicitShapeAndSkinEvaluation=true,matchedAnimationAndView=true,sceneSaved=false,playModeTested=false},Formatting.Indented));return new{images=files.Count};
 }finally{PrefabUtility.UnloadPrefabContents(root);EditorSceneManager.ClosePreviewScene(scene);}
 }
}


